insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The writer contrasts short-term popularity with long-term reliability for adult learners, as described in a training program in a central reading program context.','The writer says popularity and reliability are exactly the same.','The writer discusses reliability without mentioning popularity.','The writer points out a difference between being popular now and being dependable over time.','The writer argues that long-term reliability is impossible.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_35", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Although public recycling was initially criticized, later evidence showed that it could be useful when applied carefully in public institutions, as described in an evaluation report in a online reading program context.','The usefulness of public recycling was accepted before anyone criticized it.','Later evidence showed that public recycling should never be applied.','Early criticism proved that public recycling had no value at all.','Later evidence suggested that public recycling, despite early criticism, may have value if used carefully.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_35", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that flexible work hours solves every problem; it argues only that it can reduce one specific difficulty during periods of change, as described in a committee meeting in a evening reading program context.','According to the report, flexible work hours is not a complete solution but may help with a particular problem.','The report argues that flexible work hours solves all problems completely.','The report rejects the idea that flexible work hours can help in any way.','The report discusses many solutions but never mentions a specific problem.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_35", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in small communities, as described in a student guide in a summer reading program context.','The available data forced the researchers to reject all conclusions.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The researchers postponed collecting data after reaching a firm conclusion.','The researchers made a recommendation because the data were complete.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_35", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes when resources are limited, as described in a pilot study in a advanced reading program context.','The author believes mistakes should be ignored during practice.','The author claims feedback is useful only when students stop practicing.','The author believes practice works best if learners are told what they did wrong.','The author suggests that practice and feedback are unrelated.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_35", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
