insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes during periods of change, as described in a policy review in a evening language center context.','The author suggests that practice and feedback are unrelated.','The author believes mistakes should be ignored during practice.','The author believes practice works best if learners are told what they did wrong.','The author claims feedback is useful only when students stop practicing.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_37", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The new system was adopted not because it was cheaper, but because it made the process more transparent in small communities, as described in a classroom discussion in a summer language center context.','The new system was adopted mainly because it reduced costs.','The new system was rejected because it was not transparent.','The process became less transparent after the new system was adopted.','The main reason for adopting the new system was improved transparency rather than lower cost.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_37", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Even though the experiment was small, its results raised important questions for future research when resources are limited, as described in a research summary in a advanced language center context.','Despite its limited size, the experiment produced results that future studies should examine.','The experiment was too large to raise useful questions.','Future research became unnecessary after the experiment.','The results were ignored because the experiment was not small.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_37", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The passage implies that convenience may encourage people to use a service, but it does not guarantee satisfaction under careful supervision, as described in a public debate in a introductory language center context.','The passage denies that convenience affects service use.','The passage suggests that a convenient service can attract users without necessarily satisfying them.','The passage says convenience always guarantees satisfaction.','The passage argues that inconvenient services attract the most users.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_37", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The committee approved the plan only after several risks had been identified and addressed after initial trials, as described in a training program in a coastal public workshop context.','The committee rejected the plan because all risks were addressed.','The plan was accepted although no risks were identified.','The plan was accepted once the committee had dealt with the risks it found.','The committee approved the plan before considering any risks.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_37", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in schools, as described in an evaluation report in a urban public workshop context.','The decline in complaints was sudden and easy to explain.','Managers blamed a single change because complaints rose quickly.','Managers ignored the decline because it was caused by one change.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_37", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The writer contrasts short-term popularity with long-term reliability for adult learners, as described in a committee meeting in a northern public workshop context.','The writer points out a difference between being popular now and being dependable over time.','The writer argues that long-term reliability is impossible.','The writer discusses reliability without mentioning popularity.','The writer says popularity and reliability are exactly the same.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_37", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
